import{_ as t,o,c as d,a2 as s}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Outils MCP","description":"","frontmatter":{},"headers":[],"relativePath":"fr/mcp-tools/overview.md","filePath":"fr/mcp-tools/overview.md","lastUpdated":1784903584000}'),n={name:"fr/mcp-tools/overview.md"};function i(r,e,a,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="outils-mcp" tabindex="-1">Outils MCP <a class="header-anchor" href="#outils-mcp" aria-label="Permalink to &quot;Outils MCP&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp fournit <strong>19 outils MCP</strong> qui donnent à un agent LLM un accès complet à vos API via le Model Context Protocol. Ces outils couvrent l&#39;ensemble du flux de travail : découvrir les API disponibles, naviguer dans la hiérarchie des spécifications, rechercher et inspecter des points de terminaison, exécuter des appels API et travailler avec de grandes réponses.</p><h3 id="ce-que-les-outils-resolvent" tabindex="-1">Ce que les outils résolvent <a class="header-anchor" href="#ce-que-les-outils-resolvent" aria-label="Permalink to &quot;Ce que les outils résolvent&quot;">​</a></h3><ul><li><strong>Découverte</strong> — le LLM peut trouver des spécifications, des collections et des balises sans connaître les ID à l&#39;avance</li><li><strong>Navigation</strong> — descendre de la spécification → collection → balise → point de terminaison dans une hiérarchie structurée</li><li><strong>Recherche</strong> — recherche en texte intégral dans tous les points de terminaison lorsque vous n&#39;avez pas d&#39;ID</li><li><strong>Inspection</strong> — obtenir l&#39;objet complet de l&#39;opération OpenAPI avant d&#39;effectuer un appel</li><li><strong>Exécution</strong> — invoquer de véritables appels API avec authentification automatique</li><li><strong>Gestion des grandes réponses</strong> — structurer, compresser et découper les réponses trop volumineuses pour être incluses en ligne</li></ul><h3 id="lecture-seule-ou-modifiable" tabindex="-1">Lecture seule ou modifiable <a class="header-anchor" href="#lecture-seule-ou-modifiable" aria-label="Permalink to &quot;Lecture seule ou modifiable&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Nombre</th><th>Outils</th></tr></thead><tbody><tr><td><strong>Lecture seule</strong></td><td>17</td><td>Tous les outils de découverte, point de terminaison, recherche, inspection, info et réponse</td></tr><tr><td><strong>Modifiable</strong></td><td>2</td><td><code>invoke</code> (effectue de véritables appels HTTP), <code>auth</code> (récupère les jetons)</td></tr></tbody></table><p>Les outils en lecture seule sont marqués avec <code>ReadOnlyHint=true</code> et <code>IdempotentHint=true</code> dans le protocole MCP, signalant au LLM qu&#39;ils peuvent être appelés sans effets secondaires.</p><h3 id="gestion-des-erreurs" tabindex="-1">Gestion des erreurs <a class="header-anchor" href="#gestion-des-erreurs" aria-label="Permalink to &quot;Gestion des erreurs&quot;">​</a></h3><p>Tous les outils renvoient des erreurs sous forme d&#39;objets <code>LLMError</code> structurés avec un code lisible par machine et un message lisible qui explique ce qui n&#39;a pas fonctionné et quoi faire ensuite :</p><table tabindex="0"><thead><tr><th>Code d&#39;erreur</th><th>Signification</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>Entrée invalide (mauvais format d&#39;ID, champs obligatoires manquants)</td></tr><tr><td><code>not_found</code></td><td>Entité non trouvée dans l&#39;index ou l&#39;espace de travail</td></tr><tr><td><code>rate_limit</code></td><td>Deuxième appel <code>invoke</code> dans les 10 secondes sur le même point de terminaison</td></tr><tr><td><code>invoke_error</code></td><td>Échec de l&#39;appel HTTP, échec du téléchargement</td></tr><tr><td><code>auth_error</code></td><td>Échec de la récupération du jeton d&#39;authentification</td></tr><tr><td><code>config_error</code></td><td>Échec du chargement ou de l&#39;enregistrement du fichier de configuration</td></tr><tr><td><code>parse_error</code></td><td>Échec de l&#39;analyse du fichier de spécification</td></tr></tbody></table><h2 id="categories" tabindex="-1">Catégories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Catégories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Catégorie</th><th>Outils</th><th>Description</th></tr></thead><tbody><tr><td><strong>Découverte</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>Naviguer dans la hiérarchie des spécifications : trouver des spécifications, des collections et des balises</td></tr><tr><td><strong>Points de terminaison</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>Voir les points de terminaison à différents niveaux de la hiérarchie</td></tr><tr><td><strong>Exécution</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>Rechercher, inspecter le contrat complet et appeler des API</td></tr><tr><td><strong>Utilitaires</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>Jetons d&#39;authentification, informations d&#39;exécution et gestion des grandes réponses</td></tr><tr><td><strong>Compétences</strong></td><td><a href="/mcp-tools/skills">Guide de formatage</a></td><td>Personnaliser l&#39;affichage des réponses des outils</td></tr></tbody></table><h2 id="liste-complete" tabindex="-1">Liste complète <a class="header-anchor" href="#liste-complete" aria-label="Permalink to &quot;Liste complète&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Description</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>Lister toutes les spécifications API dans l&#39;espace de travail</td></tr><tr><td><code>spec_by_id</code></td><td>Obtenir des informations détaillées sur une spécification avec ses collections</td></tr><tr><td><code>collection_by_spec</code></td><td>Lister les collections d&#39;une spécification</td></tr><tr><td><code>collection_by_id</code></td><td>Obtenir les détails d&#39;une collection avec ses balises</td></tr><tr><td><code>tag_by_spec</code></td><td>Lister toutes les balises d&#39;une spécification</td></tr><tr><td><code>tag_by_collection</code></td><td>Lister les balises d&#39;une collection</td></tr><tr><td><code>tag_by_id</code></td><td>Obtenir les détails d&#39;une balise (ID, titre, nombre de méthodes)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>Lister tous les points de terminaison d&#39;une spécification</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Lister les points de terminaison d&#39;une collection</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Lister les points de terminaison d&#39;une balise</td></tr><tr><td><code>endpoint_by_id</code></td><td>Résumé rapide d&#39;un point de terminaison (méthode, chemin, résumé)</td></tr><tr><td><code>search</code></td><td>Recherche en texte intégral dans tous les points de terminaison</td></tr><tr><td><code>inspect</code></td><td>Détails complets de l&#39;opération OpenAPI (paramètres, schémas)</td></tr><tr><td><code>invoke</code></td><td>Exécuter un véritable appel API</td></tr><tr><td><code>auth</code></td><td>Obtenir le jeton d&#39;authentification ou les en-têtes pour une spécification</td></tr><tr><td><code>info</code></td><td>Informations d&#39;exécution (version, spécifications, configuration)</td></tr><tr><td><code>response_outline</code></td><td>Résumé structurel d&#39;un fichier de réponse volumineux</td></tr><tr><td><code>response_compress</code></td><td>Compresser une grande réponse pour l&#39;adapter en ligne</td></tr><tr><td><code>response_slice</code></td><td>Extraire un fragment d&#39;une grande réponse</td></tr></tbody></table><h2 id="hierarchie-de-navigation" tabindex="-1">Hiérarchie de navigation <a class="header-anchor" href="#hierarchie-de-navigation" aria-label="Permalink to &quot;Hiérarchie de navigation&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>Lorsque vous n&#39;avez pas d&#39;ID, utilisez <code>search</code> pour trouver des points de terminaison par requête. Lorsque <code>invoke</code> renvoie une <code>fileRef</code> (réponse trop volumineuse), utilisez <code>response_outline</code> → <code>response_compress</code> ou <code>response_slice</code> pour explorer les données.</p>`,18)])])}const b=t(n,[["render",i]]);export{h as __pageData,b as default};
